import{_ as o,r as a,o as l,c as p,e as n,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Entries Field - October CMS - 4.x","titleTemplate":false,"description":"Content Field","frontmatter":{"subtitle":"Content Field","shortname":"Entries"},"headers":[{"level":2,"title":"Applying Conditions","slug":"applying-conditions","link":"#applying-conditions","children":[{"level":3,"title":"SQL Query Condition","slug":"sql-query-condition","link":"#sql-query-condition","children":[]},{"level":3,"title":"PHP Query Scopes","slug":"php-query-scopes","link":"#php-query-scopes","children":[]}]},{"level":2,"title":"Defining the Inverse Relation","slug":"defining-the-inverse-relation","link":"#defining-the-inverse-relation","children":[]},{"level":2,"title":"List Column Display","slug":"list-column-display","link":"#list-column-display","children":[{"level":3,"title":"Display as a Counter","slug":"display-as-a-counter","link":"#display-as-a-counter","children":[]}]},{"level":2,"title":"Advanced Record Management","slug":"advanced-record-management","link":"#advanced-record-management","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/element/content/field-entries.md","filePath":"4.x/element/content/field-entries.md"}'),i={name:"4.x/element/content/field-entries.md"};function d(u,e,k,h,y,g){const s=a("pre-heading"),t=a("post-heading");return l(),p("div",null,[n(s),e[0]||(e[0]=c("h1",null,"Entries Field",-1)),n(t),e[1]||(e[1]=r(`<p><code>entries</code> - links to other entries by UUID or handle.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Author
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">source</span><span class="token punctuation">:</span> &lt;uuid<span class="token punctuation">|</span>handle<span class="token punctuation">&gt;</span>
</code></pre></div><p>The following properties are supported.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>source</strong></td><td>the related blueprint UUID or handle name.</td></tr><tr><td><strong>maxItems</strong></td><td>limits the number of entries that can be selected.</td></tr><tr><td><strong>displayMode</strong></td><td>modifies how the field is displayed. Supported values: <code>relation</code>, <code>recordfinder</code>, <code>taglist</code>, <code>controller</code>. Default: <code>relation</code>.</td></tr><tr><td><strong>conditions</strong></td><td>specifies a raw where query statement to apply to the model query.</td></tr><tr><td><strong>modelScope</strong></td><td>applies a <a href="./../../extend/database/model.html">model query scope</a> method to the <strong>related form model</strong>, can be a model method name or a static PHP class method (<code>Class::method</code>).</td></tr><tr><td><strong>inverse</strong></td><td>when defined as an inverse relationship, the name of the related field in the source blueprint.</td></tr></tbody></table></div><p>To limit the number of selectable items, use the <code>maxItems</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">maxItems</span><span class="token punctuation">:</span> <span class="token number">1</span>
</code></pre></div><p>To display a record finder instead of the typical control, use the <code>displayMode</code> property. This mode is only available when one item is selectable.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> recordfinder
</code></pre></div><p>When multiple items are available, the <code>displayMode</code> supports selecting items using a tag list.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> taglist
</code></pre></div><h2 id="applying-conditions"><a href="#applying-conditions" class="header-anchor">#</a> Applying Conditions</h2><p>You can restrict the related query using SQL or PHP using the approaches below. In the examples, the related record has a field called <code>is_featured</code> that renders as a checkbox. We can limit the related records to only those that have this checkbox marked.</p><h3 id="sql-query-condition"><a href="#sql-query-condition" class="header-anchor">#</a> SQL Query Condition</h3><p>You may limit the related model using a raw SQL query using the <code>conditions</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">categories</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Categories
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">source</span><span class="token punctuation">:</span> Blog\\Category
    <span class="token key atrule">conditions</span><span class="token punctuation">:</span> is_featured = true
</code></pre></div><h3 id="php-query-scopes"><a href="#php-query-scopes" class="header-anchor">#</a> PHP Query Scopes</h3><p>You may limit the related query using a PHP method with the <code>scope</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">basic_entries</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Basic Entry
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">source</span><span class="token punctuation">:</span> Basic\\Entry
    <span class="token key atrule">scope</span><span class="token punctuation">:</span> App\\Classes\\ScopeHelper<span class="token punctuation">:</span><span class="token punctuation">:</span>applyScope
</code></pre></div><p>This would refer to the <code>App\\Classes\\ScopeHelper</code> class that may look a file located in <strong>app/classes/ScopeHelper.php</strong>, for example.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">App<span class="token punctuation">\\</span>Classes</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">ScopeHelper</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">function</span> <span class="token function-definition function">applyScope</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_featured&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="defining-the-inverse-relation"><a href="#defining-the-inverse-relation" class="header-anchor">#</a> Defining the Inverse Relation</h2><p>In some cases you may wish to access the relationship in reverse, such as finding all posts that belong to a certain category. The <code>inverse</code> property can be used to link the relationship in the opposite direction, where the property value is set to the field name in the source blueprint.</p><p>For example, if a <strong>Blog\\Post</strong> blueprint has a <code>categories</code> relationship already defined.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">categories</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">source</span><span class="token punctuation">:</span> Blog\\Category
</code></pre></div><p>The <strong>Blog\\Category</strong> blueprint can include a <code>posts</code> field as the <code>inverse</code> of the <code>categories</code> field found in the source blueprint (above). The field can be excluded from forms by setting the <code>hidden</code> value to <code>true</code>, and this is optional.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">posts</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">source</span><span class="token punctuation">:</span> Blog\\Post
    <span class="token key atrule">inverse</span><span class="token punctuation">:</span> categories
    <span class="token key atrule">hidden</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h2 id="list-column-display"><a href="#list-column-display" class="header-anchor">#</a> List Column Display</h2><p>By default, the entries field will display as a hyperlink to the related record.</p><h3 id="display-as-a-counter"><a href="#display-as-a-counter" class="header-anchor">#</a> Display as a Counter</h3><p>To display the list column to show a counter of related records, you may use the following <a href="./../list-columns.html">column configuration</a>. The <code>relation</code> property should be set to the field name, with <code>relationCount</code> set to <code>true</code> and a <code>number</code> column type.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">categories</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Categories
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token comment"># ...</span>
    <span class="token key atrule">column</span><span class="token punctuation">:</span>
        <span class="token key atrule">relation</span><span class="token punctuation">:</span> categories
        <span class="token key atrule">relationCount</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> number
</code></pre></div><h2 id="advanced-record-management"><a href="#advanced-record-management" class="header-anchor">#</a> Advanced Record Management</h2><p>To create, update and delete items within the form, set the <code>displayMode</code> to controller to show an advanced management mode, powered by <a href="./../../extend/forms/relation-controller.html">Relation Controller behavior</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> controller
</code></pre></div><p>If the blueprint has <code>navigation</code> set to <code>false</code> then the default buttons will show <strong>Create</strong> and <strong>Delete</strong>. If the navigation is defined, then the buttons show <strong>Add</strong> and <strong>Remove</strong>. You may customize the buttons with the <code>toolbarButtons</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> create<span class="token punctuation">|</span>add<span class="token punctuation">|</span>remove<span class="token punctuation">|</span>delete
</code></pre></div><p>The various messages used in the relation controller are taken from the source blueprint <code>customMessages</code>, property, and you may also modify them using the <code>customMessages</code> on the field definition.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
        <span class="token key atrule">buttonCreate</span><span class="token punctuation">:</span> New Author
        <span class="token key atrule">titleUpdateForm</span><span class="token punctuation">:</span> Update Author
        <span class="token key atrule">titleCreateForm</span><span class="token punctuation">:</span> Create Author
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./field-nesteditems.html">Nested Items Content Field</a></li></ul></div>`,40))])}const v=o(i,[["render",d]]);export{f as __pageData,v as default};
